mapper.select:
SELECT sd.id FROM kit_knowledge_source_document sd
AND sd.deleted = 0 AND ( NOT EXISTS ( SELECT 1 FROM kit_knowledge_source_document_role open_role WHERE open_role.source_document_id = sd.id AND open_role.deleted = 0 )
OR EXISTS ( SELECT 1 FROM kit_knowledge_source_document_role hit_role WHERE hit_role.source_document_id = sd.id AND hit_role.deleted = 0 AND hit_role.role_code IN
#{roleCode}
)
)
